import { test, expect } from '@playwright/test';

test.describe('Internal Links Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should open internal link in the same tab', async ({ page, context }) => {
    // Get all pages in the context to verify no new tab is opened
    const initialPageCount = context.pages().length;

    // Click on an internal link
    const internalLink = page.getByRole('link', { name: /about/i }).first();
    await internalLink.click();

    // Verify no new tab was opened
    const finalPageCount = context.pages().length;
    expect(finalPageCount).toBe(initialPageCount);

    // Verify navigation occurred in the same tab
    await expect(page).toHaveURL(/.*about/i);
  });

  test('should maintain navigation history when clicking internal links', async ({ page }) => {
    // Navigate to initial page
    await expect(page).toHaveURL('http://localhost:3000');

    // Click first internal link
    const firstLink = page.getByRole('link', { name: /about/i }).first();
    await firstLink.click();
    await page.waitForLoadState('networkidle');

    const firstUrl = page.url();

    // Click another internal link
    const secondLink = page.getByRole('link', { name: /contact/i }).first();
    await secondLink.click();
    await page.waitForLoadState('networkidle');

    const secondUrl = page.url();

    // Verify URLs are different
    expect(firstUrl).not.toBe(secondUrl);

    // Go back and verify we return to first link's page
    await page.goBack();
    await expect(page).toHaveURL(firstUrl);
  });

  test('should not open internal links with target="_blank" in same tab', async ({ page, context }) => {
    // This test verifies the expected behavior - external links with target="_blank" should open in new tab
    // while regular internal links should open in same tab

    const newPagePromise = context.waitForEvent('page');

    // Click on a link that has target="_blank" (external link)
    const externalLink = page.getByRole('link', { name: /external/i }).first();

    // Only proceed if external link exists
    const externalLinkCount = await externalLink.count();
    if (externalLinkCount > 0) {
      await externalLink.click();

      // Wait for new page to open
      const newPage = await newPagePromise;

      // Verify a new tab was opened
      expect(context.pages().length).toBeGreaterThan(1);

      // Clean up
      await newPage.close();
    }
  });

  test('should preserve scroll position when navigating internal links', async ({ page }) => {
    // Navigate to a page with content
    await page.goto('http://localhost:3000');

    // Scroll down
    await page.evaluate(() => window.scrollTo(0, 500));
    const scrollPositionBefore = await page.evaluate(() => window.scrollY);

    // Click an internal link
    const internalLink = page.getByRole('link', { name: /services/i }).first();
    const linkCount = await internalLink.count();

    if (linkCount > 0) {
      await internalLink.click();
      await page.waitForLoadState('networkidle');

      // Verify we're on a different page (same tab)
      const currentUrl = page.url();
      expect(currentUrl).not.toBe('http://localhost:3000');

      // Scroll position should be reset on new page
      const scrollPositionAfter = await page.evaluate(() => window.scrollY);
      expect(scrollPositionAfter).toBe(0);
    }
  });

  test('should handle multiple rapid internal link clicks in same tab', async ({ page, context }) => {
    const initialPageCount = context.pages().length;

    // Get multiple internal links
    const links = page.getByRole('link').filter({ hasText: /home|about|services|contact/i });
    const linkCount = await links.count();

    if (linkCount > 0) {
      // Click first link
      await links.first().click();
      await page.waitForLoadState('networkidle');

      // Click second link rapidly
      const secondLink = page.getByRole('link', { name: /about|services/i }).first();
      const secondLinkCount = await secondLink.count();

      if (secondLinkCount > 0) {
        await secondLink.click();
        await page.waitForLoadState('networkidle');
      }

      // Verify still in same tab
      const finalPageCount = context.pages().length;
      expect(finalPageCount).toBe(initialPageCount);
    }
  });
});
